// avalia a resposta do ping ao Claude e decide se avisa o Thiago (estado em staticData, so em producao)
const st = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const code = parseInt(r.statusCode || (r.error && r.error.status) || 0, 10) || 0;
let corpo = r.body;
if (typeof corpo === 'string') { try { corpo = JSON.parse(corpo); } catch (e) {} }
const msgApi = String((corpo && corpo.error && (corpo.error.message || corpo.error.type)) || (r.error && r.error.message) || '').replace(/\s+/g, ' ').substring(0, 220);
const ok = code === 200 && corpo && Array.isArray(corpo.content);
const agora = Date.now();
const HORAS6 = 6 * 3600 * 1000;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''").replace(/\$+/g, x => "' || repeat(chr(36), " + x.length + ") || '");
const fila = txt => "INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para, status) VALUES ('5511910441709', 'Thiago', '" + esc(txt) + "', NOW() AT TIME ZONE 'America/Sao_Paulo', 'pendente') RETURNING id;";
if (ok) {
  st.falhas = 0;
  if (st.alertado_em) {
    const desde = st.fora_desde ? new Date(st.fora_desde).toISOString().substring(0, 16).replace('T', ' ') + ' UTC' : '?';
    st.alertado_em = null; st.fora_desde = null;
    return [{ json: { sql: fila('✅ O Claude voltou a responder. A Giulia já está entendendo as mensagens de novo (estava fora desde ' + desde + ').') } }];
  }
  st.fora_desde = null;
  return [];
}
st.falhas = (st.falhas || 0) + 1;
if (!st.fora_desde) st.fora_desde = agora;
// 4xx (cobranca, chave invalida, permissao, cota) = problema de conta: avisa ja. 5xx/timeout: so apos 3 seguidos.
const contaProblema = code >= 400 && code < 500;
if (!contaProblema && st.falhas < 3) return [];
if (st.alertado_em && agora - st.alertado_em < HORAS6) return [];
st.alertado_em = agora;
let causa = 'erro ' + (code || 'sem resposta');
if (/credit balance|billing|payment|outstanding/i.test(msgApi)) causa = 'CRÉDITOS: o saldo da conta da Anthropic acabou. Recarregue em console.anthropic.com → Billing';
else if (code === 401 || /api.?key|authentication/i.test(msgApi)) causa = 'CHAVE inválida ou revogada (credencial Anthropic no n8n)';
else if (code === 429) causa = 'LIMITE de uso estourado (rate limit ou limite de gasto)';
else if (code === 403) causa = 'PERMISSÃO negada (chave ou projeto)';
const txt = '🚨 Claude (IA da Giulia) fora do ar (HTTP ' + (code || '?') + '). ' + causa + '.\n'
  + 'Enquanto isso a Giulia não entende as mensagens e responde que teve um problema e pede para mandar de novo.\n'
  + (msgApi ? 'Detalhe: ' + msgApi.replace(/https?:\/\/\S+/g, '').trim() + '\n' : '')
  + 'Eu aviso de novo quando voltar.';
return [{ json: { sql: fila(txt) } }];
